# ReAct loop implementation (simplified)
import re

def react_agent(question, max_steps=5):
    prompt = build_react_prompt(question)

    for step in range(max_steps):
        response = llm.generate(prompt)

        if "Final Answer:" in response:
            return extract_final_answer(response)

        action_match = re.search(r"Action: (\w+)\((.+)\)", response)
        if action_match:
            tool_name = action_match.group(1)
            argument = action_match.group(2)
            result = execute_tool(tool_name, argument)
            prompt += f"\n{response}\nObservation: {result}"

    return "Max steps reached without answer."

def execute_tool(name, arg):
    if name == "search": return web_search(arg)
    if name == "calculate": return str(eval(arg))
    return "Unknown tool"

