# Prompt evaluation framework
import json
from difflib import SequenceMatcher

test_cases = [
    {
        "input": "Capital of France?",
        "expected": "Paris",
        "tags": ["geography", "easy"]
    },
    {
        "input": "Summarize: The quick brown fox jumps.",
        "expected": "A fox jumps.",
        "tags": ["summarization"]
    }
]

def evaluate_prompt(prompt_template, model):
    results = []
    for case in test_cases:
        actual = model.generate(prompt_template.format(input=case["input"]))
        similarity = SequenceMatcher(None, actual, case["expected"]).ratio()

        results.append({
            "input": case["input"],
            "expected": case["expected"],
            "actual": actual,
            "similarity": similarity,
            "passed": similarity > 0.8
        })

    accuracy = sum(r["passed"] for r in results) / len(results)
    return {"accuracy": accuracy, "details": results}

report = evaluate_prompt(my_prompt, gpt4)
print(f"Accuracy: {report['accuracy']:.1%}")

