# ToT implementation sketch
from typing import List

class Node:
    def __init__(self, state: str, parent=None):
        self.state = state
        self.parent = parent
        self.children = []
        self.score = 0

def generate_candidates(state: str, n: int = 3) -> List[str]:
    prompt = f"Given state '{state}', list {n} next actions. One per line."
    return llm.generate(prompt).strip().split('\n')

def evaluate_state(state: str) -> int:
    prompt = f"Rate the safety of this state 1-10: {state}. Output number only."
    return int(llm.generate(prompt))

def solve_tot(initial_state, max_depth=10):
    root = Node(initial_state)
    frontier = [root]

    for _ in range(max_depth):
        node = frontier.pop(0)
        if is_goal(node.state):
            return reconstruct_path(node)

        candidates = generate_candidates(node.state)
        for cand in candidates:
            child = Node(cand, parent=node)
            child.score = evaluate_state(cand)
            node.children.append(child)

        # Add scored children to frontier, best first
        frontier.extend(sorted(node.children, key=lambda x: x.score, reverse=True))

    return None

