# Defensive parsing with retry-on-error feedback
import json
from pydantic import ValidationError

def safe_generate(prompt, schema_model, max_retries=3):
    messages = [{"role": "system", "content": "You are a JSON-only API."},
                {"role": "user", "content": prompt}]

    for attempt in range(max_retries):
        raw = llm.generate(messages)
        try:
            data = json.loads(raw)
            validated = schema_model(**data)
            return validated
        except (json.JSONDecodeError, ValidationError) as e:
            # Feed the error back to the model
            messages.append({"role": "assistant", "content": raw})
            messages.append({
                "role": "user",
                "content": f"That output was invalid. Error: {str(e)}. Please fix and return valid JSON only."
            })

    raise RuntimeError("Failed to generate valid output after max retries.")

# Uncertainty-based routing to human review
import numpy as np

def route_for_review(prompt, response, confidence_threshold=0.7):
    '''Route low-confidence outputs to human reviewers.'''
    # Self-consistency: generate 3 answers and measure agreement
    answers = [llm.generate(prompt) for _ in range(3)]
    unique = set(a.strip().lower() for a in answers)
    agreement = 1.0 / len(unique)  # 1.0 = unanimous, 0.33 = all different

    if agreement < confidence_threshold:
        queue_for_human_review({
            'prompt': prompt,
            'responses': answers,
            'agreement': agreement,
            'reason': 'low_self_consistency'
        })
        return {'status': 'pending_review', 'response': None}

    return {'status': 'auto_approved', 'response': answers[0]}

